import { attachSaveStatus } from "./save-status.js";
import { createTrailingTask } from "./trailing-task.js";

export function createDraftEditor({ store, timers, renderDocument, renderStatus }) {
  let current = null;
  let generation = 0;
  function retire() {
    const leaving = current;
    current = null;
    if (leaving) leaving.stop();
    renderDocument(null);
    if (leaving) leaving.task.flush();
  }
  function close() {
    ++generation;
    retire();
  }
  return {
    open(id, visit) {
      const request = ++generation;
      retire();
      // A save integration may have opened or closed another visit.
      if (request !== generation) return;
      current = {
        id, visit,
        stop: attachSaveStatus(store, id, renderStatus),
        task: createTrailingTask(text => store.write(id, text), 120, timers),
      };
      renderDocument({ id, visit, text: store.read(id) });
    },
    edit(text) {
      if (current) current.task.push(text);
    },
    selection: () => current && { id: current.id, visit: current.visit },
    close,
  };
}

